-- 26 September 2026 fixed-paper source questions (15 Math + 20 Bangladesh Affairs).
-- Corrections were applied to the supplied data: the radical item has a valid key,
-- SQL quotes/typos are normalized, and explanations align with the answers.
-- Run in Supabase Dashboard → SQL Editor.

ON CONFLICT (question) DO UPDATE SET
  options = EXCLUDED.options,
  answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation,
  subject = EXCLUDED.subject,
  topic = EXCLUDED.topic,
  sub_topic = EXCLUDED.sub_topic,
  post_name = EXCLUDED.post_name;
